<?php session_start();require 'config.php';if(($_SESSION['role']??'')!=='admin'){http_response_code(403);exit('Access denied: administrators only.');}$students=(int)$db->query("SELECT COUNT(*) n FROM users WHERE role='student'")->fetch_assoc()['n'];$events=(int)$db->query('SELECT COUNT(*) n FROM events')->fetch_assoc()['n'];$latest=$db->query('SELECT name,email,created_at FROM users ORDER BY created_at DESC LIMIT 5');?><h1>Admin Dashboard</h1><p>Students: <?=$students?></p><p>Events: <?=$events?></p><h2>Latest registrations</h2><ul><?php while($u=$latest->fetch_assoc()):?><li><?=htmlspecialchars($u['name']??'')?> — <?=htmlspecialchars($u['email']??'')?> (<?=htmlspecialchars($u['created_at'])?>)</li><?php endwhile;?></ul><nav><a href="students.php">Manage students</a> | <a href="events.php">Manage events</a></nav>